export const trophyModes=Object.freeze([{id:'name',label:'Name every place'},{id:'identify',label:'Name highlighted place'},{id:'find',label:'Click the named place'}]);
export function sortQuizTrophies(trophies,by='added',names={}){
 const collator=new Intl.Collator('en',{sensitivity:'base'});return [...trophies].sort((a,b)=>by==='country'?collator.compare(names[a.country]||a.country,names[b.country]||b.country)||a.addedOrder-b.addedOrder:Date.parse(b.addedAt)-Date.parse(a.addedAt)||b.addedOrder-a.addedOrder);
}
export function trophyProgress(trophy,snapshot){
 const candidates=(snapshot?.bests||[]).filter(a=>a.country===trophy.country&&a.level===1&&a.fullRound),scopes=trophy.scopeMinimums?Object.entries(trophy.scopeMinimums).map(([id,minimum])=>({id,minimum})):[{id:'',minimum:trophy.minimum}];
 const modes=trophyModes.map(mode=>{const groups=scopes.map(scope=>{const records=candidates.filter(a=>a.mode===mode.id&&(a.scope||'')===scope.id&&a.total>=scope.minimum),earned=records.filter(a=>a.bestCorrect===a.total&&Number.isFinite(a.fastestMs)&&a.fastestMs>0).sort((a,b)=>a.fastestMs-b.fastestMs)[0],best=earned||records.sort((a,b)=>b.bestCorrect/b.total-a.bestCorrect/a.total)[0];return{scope:scope.id,earned:!!earned,correct:best?.bestCorrect||0,total:best?.total||scope.minimum,fastestMs:earned?.fastestMs??null};}),earned=groups.every(g=>g.earned);return{...mode,earned,correct:groups.reduce((n,g)=>n+g.correct,0),total:groups.reduce((n,g)=>n+g.total,0),fastestMs:earned?groups.reduce((n,g)=>n+g.fastestMs,0):null,nextScope:groups.find(g=>!g.earned)?.scope||scopes[0].id};});
 const completedModes=modes.filter(m=>m.earned).length;return{earned:completedModes===trophyModes.length,completedModes,percent:Math.round(completedModes/trophyModes.length*100),modes};
}
